"""Viterbi decoding with backpointers on two small HMMs."""

def viterbi(words, tags, start, A, B):
    V = [{}]; back = [{}]
    for s in tags:
        V[0][s] = start.get(s, 0) * B[s].get(words[0], 0); back[0][s] = None
    for t in range(1, len(words)):
        V.append({}); back.append({})
        for s in tags:
            best_prev, best = None, 0.0
            for sp in tags:
                sc = V[t-1][sp] * A[sp].get(s, 0)
                if sc > best: best_prev, best = sp, sc
            V[t][s] = best * B[s].get(words[t], 0); back[t][s] = best_prev
    last = max(V[-1], key=V[-1].get); path = [last]
    for t in range(len(words) - 1, 0, -1):
        path.append(back[t][path[-1]])
    return V, path[::-1]

# 1. 'the doctor is in' (transitions not listed are 0)
tags = ["Det", "Noun", "Verb", "Prep", "Adv"]
start = {"Det": 0.3}
A = {"Det": {"Noun": 0.9, "Verb": 0.01}, "Noun": {"Noun": 0.2, "Verb": 0.4, "Prep": 0.3},
     "Verb": {"Verb": 0.05, "Prep": 0.2, "Adv": 0.1}, "Prep": {}, "Adv": {}}
B = {"Det": {"the": 0.7}, "Noun": {"doctor": 0.4, "is": 0.1}, "Verb": {"doctor": 0.1, "is": 0.9},
     "Prep": {"in": 1.0}, "Adv": {"in": 0.1}}
words = "the doctor is in".split()
V, path = viterbi(words, tags, start, A, B)
for w, col in zip(words, V):
    print(f"{w:7s}", "  ".join(f"{s}={col[s]:.6f}" for s in tags if col[s] > 0))
print("best path:", " ".join(f"{w}/{t}" for w, t in zip(words, path)))

# one cell by hand
print(f"cell: from Verb 0.03*0.2 = {0.03*0.2:.4f}, from Noun 0.0015*0.3 = {0.0015*0.3:.5f} -> keep Verb")

# 2. Two-day weather HMM, observations 3 then 1 ice creams
tags2 = ["H", "C"]; start2 = {"H": 0.8, "C": 0.2}
A2 = {"H": {"H": 0.6, "C": 0.4}, "C": {"H": 0.5, "C": 0.5}}
B2 = {"H": {3: 0.4, 1: 0.2}, "C": {3: 0.1, 1: 0.5}}
V2, path2 = viterbi([3, 1], tags2, start2, A2, B2)
for t, col in enumerate(V2):
    print(f"day {t+1}: H={col['H']:.4f} C={col['C']:.4f}")
print("best weather:", "".join(path2))

# 3. Cost: T^2 * n versus T^n
for T, n in [(5, 4), (45, 10), (45, 25)]:
    print(f"T={T}, n={n}: Viterbi ~{T*T*n:,} steps vs {T**n:.2e} sequences")
